	if a.pd == nil {
		return nil, fmt.Errorf("IDL app system is not bound: call milon.NewClient first")
	}
	args := provider.Args{}
	// parent_block_hash: B256
	args["parent_block_hash"] = a.parent_block_hash
	// entropy: B256
